import { expect, Page } from '@playwright/test';

/**
 * Page Object — Cart – Katalon Shop.
 * https://cms.demo.katalon.com/cart/
 *
 * Generated by the Zennx Playwright studio from a recorded session.
 * Locators live here and nowhere else, so a renamed button is one edit.
 */
export class CartPage {
    readonly page: Page;

    private readonly happyNinjaQuantity = () => this.page.getByLabel('Happy Ninja quantity');
    private readonly updateCartButton = () => this.page.getByRole('button', { name: 'Update cart' });
    private readonly proceedToCheckoutLink = () => this.page.getByRole('link', { name: 'Proceed to checkout' });

    constructor(page: Page) {
        this.page = page;
    }

    async fillHappyNinjaQuantity(value: string): Promise<void> {
        await this.happyNinjaQuantity().fill(value);
    }

    async clickHappyNinjaQuantity(): Promise<void> {
        await this.happyNinjaQuantity().click();
    }

    async clickUpdateCartButton(expectedQuantity?: string): Promise<void> {
        await this.updateCartButton().click();
        await expect(this.page.getByRole('alert').filter({ hasText: 'Cart updated' })).toBeVisible();
        if (expectedQuantity !== undefined) {
            await expect(this.happyNinjaQuantity()).toHaveValue(expectedQuantity);
        }
    }

    async clickProceedToCheckoutLink(): Promise<void> {
        await this.proceedToCheckoutLink().click();
    }
}
